CREATE DATABASE ERPSystem;
GO
USE ERPSystem;
GO
CREATE TABLE Products(Id INT IDENTITY PRIMARY KEY, Code NVARCHAR(50) NOT NULL UNIQUE, Name NVARCHAR(200) NOT NULL, Barcode NVARCHAR(100) NULL UNIQUE, PurchasePrice DECIMAL(18,2) NOT NULL DEFAULT 0, SalePrice DECIMAL(18,2) NOT NULL DEFAULT 0, VatRate DECIMAL(5,2) NOT NULL DEFAULT 20, Unit NVARCHAR(20) NOT NULL DEFAULT N'Adet', IsActive BIT NOT NULL DEFAULT 1, CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE Warehouses(Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(100) NOT NULL, IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE WarehouseStocks(Id INT IDENTITY PRIMARY KEY, WarehouseId INT NOT NULL REFERENCES Warehouses(Id), ProductId INT NOT NULL REFERENCES Products(Id), Quantity DECIMAL(18,3) NOT NULL DEFAULT 0, CONSTRAINT UQ_WarehouseProduct UNIQUE(WarehouseId,ProductId));
CREATE TABLE Customers(Id INT IDENTITY PRIMARY KEY, Code NVARCHAR(50) NOT NULL UNIQUE, Name NVARCHAR(200) NOT NULL, Phone NVARCHAR(50), TaxNo NVARCHAR(50), Balance DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE Suppliers(Id INT IDENTITY PRIMARY KEY, Code NVARCHAR(50) NOT NULL UNIQUE, Name NVARCHAR(200) NOT NULL, Phone NVARCHAR(50), TaxNo NVARCHAR(50), Balance DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE Sales(Id BIGINT IDENTITY PRIMARY KEY, CustomerId INT NULL REFERENCES Customers(Id), WarehouseId INT NOT NULL REFERENCES Warehouses(Id), SaleDate DATETIME2 NOT NULL DEFAULT SYSDATETIME(), SubTotal DECIMAL(18,2) NOT NULL, VatTotal DECIMAL(18,2) NOT NULL, GrandTotal DECIMAL(18,2) NOT NULL, CostTotal DECIMAL(18,2) NOT NULL DEFAULT 0, PaymentType NVARCHAR(30) NOT NULL);
CREATE TABLE SaleItems(Id BIGINT IDENTITY PRIMARY KEY, SaleId BIGINT NOT NULL REFERENCES Sales(Id), ProductId INT NOT NULL REFERENCES Products(Id), Quantity DECIMAL(18,3) NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL, VatRate DECIMAL(5,2) NOT NULL, UnitCost DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE CashAccounts(Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(100) NOT NULL, Balance DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE CashTransactions(Id BIGINT IDENTITY PRIMARY KEY, CashAccountId INT NOT NULL REFERENCES CashAccounts(Id), Amount DECIMAL(18,2) NOT NULL, Type NVARCHAR(20) NOT NULL, Description NVARCHAR(500), CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE BankAccounts(Id INT IDENTITY PRIMARY KEY, BankName NVARCHAR(100) NOT NULL, AccountName NVARCHAR(100) NOT NULL, IBAN NVARCHAR(50) NULL, AccountNumber NVARCHAR(50) NULL, Branch NVARCHAR(100) NULL, Currency NVARCHAR(10) NOT NULL DEFAULT N'TRY', OpeningBalance DECIMAL(18,2) NOT NULL DEFAULT 0, CurrentBalance DECIMAL(18,2) NOT NULL DEFAULT 0, ActualBalance DECIMAL(18,2) NOT NULL DEFAULT 0, PosCommissionRate DECIMAL(5,2) NOT NULL DEFAULT 3.99, PosValourDays INT NOT NULL DEFAULT 2, IsDefault BIT NOT NULL DEFAULT 0, IsActive BIT NOT NULL DEFAULT 1, CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE PosTransactions(Id BIGINT IDENTITY PRIMARY KEY, SaleId BIGINT NULL REFERENCES Sales(Id), SaleDate DATETIME2 NOT NULL, GrossAmount DECIMAL(18,2) NOT NULL, CommissionRate DECIMAL(5,2) NOT NULL, CommissionAmount DECIMAL(18,2) NOT NULL, NetAmount DECIMAL(18,2) NOT NULL, ExpectedDate DATETIME2 NOT NULL, ActualPaymentDate DATETIME2 NULL, ActualPaidAmount DECIMAL(18,2) NULL, BankAccountId INT NULL REFERENCES BankAccounts(Id), Status NVARCHAR(30) NOT NULL DEFAULT N'Bekliyor', Description NVARCHAR(500) NULL);
CREATE TABLE BankTransactions(Id BIGINT IDENTITY PRIMARY KEY, BankAccountId INT NOT NULL REFERENCES BankAccounts(Id), TransactionType NVARCHAR(50) NOT NULL, Direction NVARCHAR(20) NOT NULL, Inflow DECIMAL(18,2) NOT NULL DEFAULT 0, Outflow DECIMAL(18,2) NOT NULL DEFAULT 0, BalanceAfter DECIMAL(18,2) NOT NULL DEFAULT 0, Description NVARCHAR(500) NULL, PaymentMethod NVARCHAR(50) NULL, ReferenceId BIGINT NULL, ReferenceType NVARCHAR(30) NULL, [User] NVARCHAR(100) NOT NULL DEFAULT N'Yönetici', CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE Expenses(Id BIGINT IDENTITY PRIMARY KEY, Category NVARCHAR(100) NOT NULL, Amount DECIMAL(18,2) NOT NULL, Description NVARCHAR(500), ExpenseDate DATETIME2 NOT NULL DEFAULT SYSDATETIME());
CREATE TABLE DailyClosures(Id BIGINT IDENTITY PRIMARY KEY, ClosureDate DATE NOT NULL, ClosedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(), TotalRevenue DECIMAL(18,2) NOT NULL DEFAULT 0, TotalCash DECIMAL(18,2) NOT NULL DEFAULT 0, TotalCreditCard DECIMAL(18,2) NOT NULL DEFAULT 0, TotalOnAccount DECIMAL(18,2) NOT NULL DEFAULT 0, TotalCost DECIMAL(18,2) NOT NULL DEFAULT 0, TotalProfit DECIMAL(18,2) NOT NULL DEFAULT 0, TotalExpenses DECIMAL(18,2) NOT NULL DEFAULT 0, SalesCount INT NOT NULL DEFAULT 0, Notes NVARCHAR(500) NULL);
